package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.os.*;
import org.json.*;
import okhttp3.*;
/** One authenticated foreground socket, independent channels and authorized refetches. */
final class NativeRealtime {
 interface Listener {void connection(boolean ready);void change(String table,String type,String id);}
 private final Context context;private final Listener listener;private final Handler main=new Handler(Looper.getMainLooper());private final OkHttpClient client=new OkHttpClient.Builder().build();private final RealtimePolicy policy=new RealtimePolicy();private final java.util.Map<String,String> joins=new java.util.HashMap<>();private WebSocket socket;private boolean active,connecting;private int epoch,ref,failures;private String user="",token="";private long frameAt;private final Runnable reconnect=()->connect();
 NativeRealtime(Context c,Listener l){context=c.getApplicationContext();listener=l;}
 void foreground(boolean value){if(active==value)return;active=value;if(value)connect();else stop();}
 private boolean session(int ticket){return active&&ticket==epoch&&user.equals(SessionPreferences.get(context).getString("user_id",""))&&token.equals(SessionPreferences.get(context).getString("access_token",""))&&SessionPreferences.get(context).getLong("expires_at",0)>System.currentTimeMillis();}
 private void stop(){epoch++;connecting=false;main.removeCallbacksAndMessages(null);if(socket!=null)socket.cancel();socket=null;policy.clear();joins.clear();listener.connection(false);}
 private void lost(int ticket){if(ticket!=epoch)return;stop();if(active)main.postDelayed(reconnect,RealtimePolicy.retry(failures++));}
 private void connect(){if(!active||socket!=null||connecting)return;connecting=true;int ticket=++epoch;new Thread(()->{try{String auth=AuthSession.token(context),uid=SessionPreferences.get(context).getString("user_id","");String[] config=SupabaseAuthClient.loadConfig();String url=config[0].replace("https://","wss://")+"/realtime/v1/websocket?apikey="+java.net.URLEncoder.encode(config[1],"UTF-8")+"&vsn=1.0.0";main.post(()->{if(ticket!=epoch||!active)return;connecting=false;user=uid;token=auth;socket=client.newWebSocket(new Request.Builder().url(url).build(),new WebSocketListener(){public void onOpen(WebSocket ws,Response response){main.post(()->{if(!session(ticket)){lost(ticket);return;}frameAt=SystemClock.elapsedRealtime();try{for(String table:RealtimePolicy.TABLES){JSONObject filter=new JSONObject().put("event","*").put("schema","public").put("table",table);String join=String.valueOf(++ref);joins.put(table,join);send(topic(table),"phx_join",new JSONObject().put("access_token",token).put("config",new JSONObject().put("private",false).put("broadcast",new JSONObject().put("ack",false).put("self",false)).put("presence",new JSONObject().put("enabled",false)).put("postgres_changes",new JSONArray().put(filter))),join,join);}main.postDelayed(()->{if(ticket==epoch&&!policy.ready())lost(ticket);},20000);main.postDelayed(heartbeat,15000);}catch(JSONException e){lost(ticket);}});}public void onMessage(WebSocket ws,String text){main.post(()->{if(session(ticket))receive(text,ticket);else lost(ticket);});}public void onFailure(WebSocket ws,Throwable error,Response response){main.post(()->lost(ticket));}public void onClosed(WebSocket ws,int code,String reason){main.post(()->lost(ticket));}});});}catch(Exception e){main.post(()->lost(ticket));}},"chat-realtime").start();}
 private String topic(String table){return "realtime:native-"+table+"-"+user;}
 private void send(String topic,String event,JSONObject payload,String reference,String join){try{JSONObject frame=new JSONObject().put("topic",topic).put("event",event).put("payload",payload).put("ref",reference);if(join!=null)frame.put("join_ref",join);if(socket!=null)socket.send(frame.toString());}catch(JSONException ignored){}}
 private final Runnable heartbeat=new Runnable(){public void run(){if(!active||socket==null)return;if(!session(epoch)||SystemClock.elapsedRealtime()-frameAt>45000){lost(epoch);return;}send("phoenix","heartbeat",new JSONObject(),String.valueOf(++ref),null);main.postDelayed(this,15000);}};
 private void receive(String text,int ticket){if(text.length()>1048576)return;frameAt=SystemClock.elapsedRealtime();try{JSONObject frame=new JSONObject(text);String event=frame.optString("event"),channel=frame.optString("topic");JSONObject payload=frame.optJSONObject("payload");if(payload==null||channel.equals("phoenix"))return;String table=null;for(String candidate:RealtimePolicy.TABLES)if(topic(candidate).equals(channel)){table=candidate;break;}if(table==null)return;
  if(event.equals("phx_reply")&&joins.get(table).equals(frame.optString("ref"))){if(!"ok".equals(payload.optString("status"))){lost(ticket);return;}JSONObject response=payload.optJSONObject("response");JSONArray subscriptions=response==null?null:response.optJSONArray("postgres_changes");if(subscriptions==null){lost(ticket);return;}for(int i=0;i<subscriptions.length();i++){JSONObject sub=subscriptions.optJSONObject(i);if(sub!=null&&table.equals(sub.optString("table"))&&"public".equals(sub.optString("schema")))policy.joined(table,sub.optLong("id",-1));}listener.connection(policy.ready());if(policy.ready()){failures=0;listener.change("","SYNC","");}return;}
  if(event.equals("system")&&"error".equals(payload.optString("status"))){lost(ticket);return;}if(event.equals("phx_error")||event.equals("phx_close")){lost(ticket);return;}if(!event.equals("postgres_changes"))return;JSONArray ids=payload.optJSONArray("ids");boolean accepted=false;if(ids!=null)for(int i=0;i<ids.length();i++)accepted|=policy.accepts(table,ids.optLong(i,-1));if(!accepted)return;JSONObject data=payload.optJSONObject("data");if(data==null||!table.equals(data.optString("table"))||!"public".equals(data.optString("schema")))return;String type=data.optString("type");if(!java.util.Arrays.asList("INSERT","UPDATE","DELETE").contains(type))return;JSONObject record=data.optJSONObject(type.equals("DELETE")?"old_record":"record");String id=record==null?"":record.optString("message_id",record.optString("id",""));if(!id.isEmpty()&&!ItemEditInput.validId(id))id="";listener.change(table,type,id);
 }catch(JSONException ignored){}}
}
